/* ============================================================================
   pdx-fd-oge.js — PRESIDENT TRUMP'S OGE FORM 278e LINES, FOR THE WEALTH GRAPH
   ============================================================================
   Data only. The rows below are merged into pdx-finance.js's holdings table by
   PDXFinance._mergeHoldings(), and from there every rule in that file applies:
   the gate checks each stored midpoint or floor against its filed band, the
   newest form must be the document the disclosure pill names, and nothing here
   is ever added together.

   WHY A SEPARATE FILE. Two annual reports carry several thousand lines between
   them. Shipping them inside pdx-finance.js would make every document with a
   letterhead parse them on load, for one person file. This file is fetched by
   finance-lane.js only when that person's disclosures block is drawn, and is
   not in the service worker's precached shell.

   HOW THE LINES WERE READ. From the PDFs' own text layer, on OGE's site:
   Part 2 Schedule 1 (the filer's business entities) and Part 6 (other assets
   and income). Rows were split by position on the page, and every asset name
   was confirmed against a second, independent extraction of the same page;
   a row whose name could not be confirmed, or whose description cannot be read
   off the text layer, is left out and counted in the comment above its form.
   Names are quoted as the text layer gives them — some pages of the 2026
   report print names with no spaces ("BOEINGCO"), and they are kept that way.
   Lines whose value box is off the ladder — 'None (or less than $1,001)',
   'Value not readily ascertainable', a 'See line' cross-reference with no
   value, or a non-standard range such as '$15,001 to $25,000' — are left out
   rather than squeezed onto a rung.

   WHICH YEAR. Both reports print 2025 in their 'Year' field. The June 2025
   report covers calendar 2024 (it holds bills due in early 2025 and reports
   2024 entity changes); the June 2026 report covers calendar 2025 (its
   transactions and dissolved entities are dated 2025). Each column is dated
   by the calendar year the report covers, the same convention the House
   Clerk's 'Filing Year' uses.
   ========================================================================= */
